// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Ensure that caller is either approved or not; we don't need to toggle owner
        // The reference C: if caller is approved, logRegisteredPubkey returns true; else false.
        bool approved = c.approvedToLog(caller);
        // Call logRegisteredPubkey with dummy bytes32 values
        bool result = c.logRegisteredPubkey(keccak256(abi.encode(caller)), keccak256(abi.encode(caller, 1)));
        assertTrue(result == approved);
    }
}

